// Lấy nút thêm vào giỏ hàng từ DOM
const addToCartBtn = document.getElementById('add-to-cart-btn');

// Đăng ký sự kiện click
addToCartBtn.addEventListener('click', function() {
  console.log('Người dùng đã nhấp nút thêm sản phẩm!');
});

// Lấy thẻ sản phẩm từ DOM
const productCard = document.getElementById('product-card');

// Đăng ký sự kiện mouseover để làm nổi bật thẻ sản phẩm
productCard.addEventListener('mouseover', function() {
  productCard.style.borderColor = '#007bff';
});

// Lấy ảnh sản phẩm từ DOM
const productImage = document.getElementById('product-image');

// Đăng ký sự kiện dblclick để phóng to hình ảnh
productImage.addEventListener('dblclick', function() {
  productImage.style.transform = 'scale(1.5)';
});

