// Chọn phần tử nút bấm và phần tử thông báo trạng thái
const addToCartButton = document.getElementById('btn-add-cart');
const statusMessage = document.getElementById('cart-status-message');

// Đăng ký sự kiện click bằng addEventListener
addToCartButton.addEventListener('click', function() {
    // Cập nhật nội dung văn bản thông báo
    statusMessage.textContent = 'Đã thêm sản phẩm vào giỏ thành công!';

    // Thay đổi màu nền của nút bấm thành màu xanh lá
    addToCartButton.style.backgroundColor = '#28a745';
    addToCartButton.style.color = '#ffffff';
});

// Chọn các phần tử HTML trên giao diện sản phẩm
const productItem = document.getElementById('product-item');
const discountBadge = document.getElementById('discount-badge');
const cartCounter = document.getElementById('cart-counter');

// Khai báo biến lưu trữ số lượng sản phẩm đã chọn
let totalCartItems = 0;

// 1. Lắng nghe sự kiện di chuột vào thẻ sản phẩm
productItem.addEventListener('mouseover', function() {
    discountBadge.style.display = 'inline-block';
    productItem.style.border = '2px solid #ff4d4f';
});

// 2. Lắng nghe sự kiện nhấp chuột chọn mua sản phẩm
productItem.addEventListener('click', function() {
    totalCartItems = totalCartItems + 1;
    cartCounter.textContent = totalCartItems;
});

// Chọn các phần tử DOM tương tác
const productCard = document.getElementById('product-card');
const favoriteButton = document.getElementById('btn-favorite');
const productImage = document.getElementById('product-image');
const previewNotice = document.getElementById('preview-notice');

// Biến cờ (flag) quản lý trạng thái yêu thích
let isFavorite = false;

// 1. Tương tác mouseover: Làm nổi bật nền thẻ khi rê chuột vào
productCard.addEventListener('mouseover', function() {
    productCard.style.backgroundColor = '#f8f9fa';
});

// 2. Tương tác click: Toggle chuyển đổi trạng thái nút Yêu thích
favoriteButton.addEventListener('click', function() {
    if (isFavorite === false) {
        favoriteButton.textContent = '❤️ Đã yêu thích';
        favoriteButton.style.color = '#dc3545';
        isFavorite = true;
    } else {
        favoriteButton.textContent = '🤍 Thêm vào yêu thích';
        favoriteButton.style.color = '#6c757d';
        isFavorite = false;
    }
});

// 3. Tương tác dblclick: Xem ảnh chi tiết khi nhấp đúp vào hình ảnh
productImage.addEventListener('dblclick', function() {
    previewNotice.textContent = 'Đang mở ảnh sản phẩm ở độ phân giải cao...';
    previewNotice.style.display = 'block';
});

